import { registerScript, ABrain, BuffType, Console, LanguageMgr, __fmt, __int } from "../../runtime.js";

export class FourNormalWolfNpc extends ABrain {
  m_targetPlayer = null;
  friendlyNpcId = 4105;
  friendBoss = null;
  OpenEye = false;
  OnBeginSelfTurn() {
            super.OnBeginSelfTurn();
        }
  OnBeginNewTurn() {
            super.OnBeginNewTurn();
            this.Body.CurrentDamagePlus = 1;
            this.Body.CurrentShootMinus = 1;

            if (this.OpenEye)
                this.Body.Config.HaveShield = true;
            else
                this.Body.Config.HaveShield = false;
        }
  OnCreated() {
            super.OnCreated();
            if(this.friendBoss == null)
            {
                // create friend bosss
                for(const boss of this.Game.FindLivingTurnBossWithID(this.friendlyNpcId))
                {
                    this.friendBoss = boss;
                    break;
                }
            }
        }
  OnStartAttacking() {
            super.OnStartAttacking();
            if (__int(this.friendBoss.Properties1) == 0 && this.OpenEye == true)
            {
                // change state B -> A
                this.Body.PlayMovie("BtoA", 1000, 4000);
                this.Body.CallFuction((this.RemoveTargetPlayer.bind(this)), 5000);
                this.OpenEye = false;
            }
            else if (__int(this.friendBoss.Properties1) == 1 && this.OpenEye == false)
            {
                this.Body.PlayMovie("AtoB", 2000, 4000);
                this.Body.CallFuction((this.FindRandomPlayer.bind(this)), 4000);
                this.OpenEye = true;
            }
            else if (this.OpenEye == true && this.m_targetPlayer != null)
            {
                let rand = this.Game.Random.Next(100);
                if (rand < 50 && this.Body.Distance(this.m_targetPlayer.X, this.m_targetPlayer.Y) > 600)
                {
                    // jump to target
                    this.JumpToTargetPlayer();
                }
                else
                {
                    this.RunToTargetPlayer();
                }
            }
            else if (this.OpenEye == false)
            {
                this.RandomMove();
            }
            else
            {
                Console.WriteLine("eye: " + this.OpenEye + " - friendBoss.Properties1: " + this.friendBoss.Properties1);
            }
        }
  RandomMove() {
            this.Body.ChangeDirection(-1, 1200);
            this.Body.ChangeDirection(1, 1800);
            this.Body.ChangeDirection(-1, 2300);
            let dismove = this.Game.Random.Next(-300, 300);
            this.Body.MoveTo(this.Body.X + dismove, this.Body.Y, "walkA", 3500, this.NothingAction.bind(this));
        }
  NothingAction() {
            this.Body.ChangeDirection(1, 500);
            this.Body.ChangeDirection(-1, 1000);
            this.Body.PlayMovie("beatA", 1000, 2000, this.SetState.bind(this));
        }
  FindRandomPlayer() {
            this.m_targetPlayer = this.Game.FindRandomPlayer();

            if(this.m_targetPlayer != null)
            {
                this.Body.ChangeDirection(this.m_targetPlayer, 500);
                // notice player
                ((this.Game)).SendPlayersPicture(this.m_targetPlayer, __int(BuffType.Targeting), true);
                this.Body.Say(__fmt(LanguageMgr.GetTranslation("GameServerScript.AI.NPC.FourNormalWolfNpc.msg1", this.m_targetPlayer.PlayerDetail.PlayerCharacter.NickName)), 0, 2000, 0);
                this.Body.CallFuction(this.SetState.bind(this), 5000);
            }
        }
  RemoveTargetPlayer() {
            if (this.m_targetPlayer != null)
            {
                ((this.Game)).SendPlayersPicture(this.m_targetPlayer, __int(BuffType.Targeting), false);
                this.m_targetPlayer = null;
            }
            this.Body.CallFuction(this.SetState.bind(this), 1000);
        }
  RunToTargetPlayer() {
            this.Body.ChangeDirection(this.m_targetPlayer, 200);

            let dis = this.Body.Distance(this.m_targetPlayer.X, this.m_targetPlayer.Y);

            if(dis > 600)
                this.Body.MoveTo(this.m_targetPlayer.X, this.m_targetPlayer.Y, "walkB", 2200, this.BeatTargetPlayer.bind(this), 10);
            else
                this.Body.MoveTo(this.m_targetPlayer.X, this.m_targetPlayer.Y, "walkC", 2200, this.BeatTargetPlayer.bind(this), 5);
        }
  JumpToTargetPlayer() {
            this.Body.ChangeDirection(this.m_targetPlayer, 200);
            
            this.Body.PlayMovie("jump", 2000, 0);

            ((this.Game)).SendObjectFocus(this.m_targetPlayer, 1, 5000, 0);

            this.Body.BoltMove(this.m_targetPlayer.X, this.m_targetPlayer.Y, 6000);

            this.Body.PlayMovie("fall", 7000, 0);

            this.Body.RangeAttacking(this.m_targetPlayer.X - 100, this.m_targetPlayer.X + 100, "cry", 8000, null);

            this.Body.CallFuction((this.BeatTargetPlayer.bind(this)), 8500);
        }
  BeatTargetPlayer() {
            this.Body.CurrentDamagePlus = 2;
            this.Body.Beat(this.m_targetPlayer, "beatB", 0, 0, 0); //1000
            this.Body.CallFuction((this.SetState.bind(this)), 4000);
        }
  OnAfterTakedBomb() {
            super.OnAfterTakedBomb();
            if (this.OpenEye == false)
            {
                // get blood
                let bloodReduce = this.friendBoss.Blood - this.Body.Blood;

                this.friendBoss.AddBlood(-bloodReduce, 1);

            }
        }
  SetState() {
            if (this.OpenEye)
            {
                //Body.PlayMovie("standB", 0, 0);
                ((this.Game)).SendLivingActionMapping(this.Body, "stand", "standB");
            }
            else
            {
                //Body.PlayMovie("standA", 0, 0);
                ((this.Game)).SendLivingActionMapping(this.Body, "stand", "standA");
            }
        }
  OnStopAttacking() {
            super.OnStopAttacking();
        }
}
